var b=UnityEngine.Object.FindAnyObjectByType<BuildingController>(); var ui=b.ui; var r=b.recipes.First(x=>x.result.Id=="wood_shovel"); var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic; var select=typeof(ConstructionUI).GetMethod("SelectRecipe",flags); var confirm=typeof(ConstructionUI).GetMethod("ConfirmPurchase",flags); int before=b.inventory.Count(r.result); int wood=b.inventory.Count(r.ingredients[0].item); ui.CancelPurchase(); bool cancel=b.inventory.Count(r.result)==before && b.inventory.Count(r.ingredients[0].item)==wood; select.Invoke(ui,new object[]{r}); confirm.Invoke(ui,null); confirm.Invoke(ui,null); return new{cancelPreserved=cancel,oneWeapon=b.inventory.Count(r.result)==before+1,exactCost=b.inventory.Count(r.ingredients[0].item)==wood-r.ingredients[0].amount,closed=!ui.PurchaseOpen};
